INSERT INTO knowledge_category (id, name, description, sort_order, is_enabled) VALUES
(1, '入学事务', '报到注册、网上预报到、军训、入学体检、大学生医保、党团组织关系转接、户口迁移、绿色通道与教材领取等新生入学事项', 1, 1),
(2, '教学教务', '选课与退补选、绩点与学分制、转专业、奖学金评定、四六级报名、补考缓考、课表查询与证明打印等教学事务', 2, 1),
(3, '校园生活', '图书馆、体育场馆、食堂供餐、校区校车、快递收发、校医院就医等校园日常生活服务', 3, 1),
(4, '宿舍生活', '犀浦/九里宿舍园区分布、宿舍电费充值、设施报修与后勤服务电话', 4, 1),
(5, '网络服务', '校园一卡通、校园网与 SWJTU-WiFi 认证、交大 VPN、交大 ID、学生邮箱、交大云盘、企业微信等信息化服务', 5, 1),
(6, '安全须知', '防范电信诈骗、校园防盗、宿舍消防与用电、校园交通、24 小时报警求助等安全事项', 6, 1);
INSERT INTO location (id, name, campus, building, floor, room, description) VALUES
(1, '犀浦校区图书馆', '犀浦', '图书馆', NULL, NULL, '犀浦校区主要藏书借阅与自习场所,提供借还书、自习空间、研讨间、数字资源检索等服务;空间/座位通过图书馆空间预约系统(zuowei.lib.swjtu.edu.cn)预约。一楼B区设信网处一卡通服务前台,科技查新工作站位于B403/B404。开放时间以图书馆官网最新公告为准。'),
(2, '图书馆一楼B区信网处一卡通服务前台', '犀浦', '图书馆', '1楼', 'B区信网处服务前台', '校园一卡通服务点,办理校园卡相关业务(须出示本人有效证件);一卡通用于食堂就餐、超市购物、图书馆出入、宿舍门禁、校车乘坐等校内消费与身份识别。咨询电话028-66366569。'),
(3, '犀浦校区综合楼', '犀浦', '综合楼', '2楼等', '222(教务科/选课咨询)', '犀浦校区综合办公与教学服务楼:教务科、选课系统咨询服务台(222室,028-66366253/66367209)设于此;2楼教务处旁及学生服务大厅设有证明自助打印机;楼外(国旗台附近)为综合楼校车站,九里—犀浦校车与东部校区校车均停靠。'),
(4, '犀浦校区第二教学楼(2教)', '犀浦', '第二教学楼', '1楼', '2115、2117(文印印务)', '犀浦校区主要教学楼之一,设师生服务大厅:文印印务窗口(2115、2117室,周一至周五8:30-12:00、14:00-17:30,028-66368457)提供打印复印;1楼设宿舍电费线下购电点;学生服务大厅亦位于2教。'),
(5, '天佑斋学生宿舍群(犀浦南区)', '犀浦', '天佑斋(若干栋)', NULL, NULL, '犀浦校区南区学生宿舍园区。2栋西侧为南区临时菜鸟驿站(快递点);3号、17号楼设有物业便利店(6:40-23:00)。宿舍设施报修028-66361116。'),
(6, '鸿哲斋学生宿舍群(犀浦)', '犀浦', '鸿哲斋(若干栋)', NULL, NULL, '犀浦校区学生宿舍园区之一,与天佑斋同为犀浦校区主要学生生活区,宿舍配套独立卫浴等生活设施,物业与报修服务覆盖全园区。'),
(7, '犀浦学生一食堂', '犀浦', '学生一食堂', '1-2楼', '二楼为清真食堂', '犀浦校区学生食堂,提供日常饭菜、特色套餐与川式小吃;二楼为清真食堂,服务少数民族学生餐饮。服务电话028-66366453(一楼)、028-66365557(二楼/清真)。'),
(8, '犀浦学生二食堂', '犀浦', '学生二食堂', '1-3楼', '二楼锦华苑餐厅', '犀浦校区学生食堂,二楼为锦华苑餐厅(电话18870215611);三楼设大学生活动中心,学院活动常在此举办。'),
(9, '犀浦学生三食堂', '犀浦', '学生三食堂', '1-2楼', '二楼风华苑餐厅', '犀浦校区学生食堂,二楼为风华苑餐厅(028-66363699、028-66361888),一楼电话028-66365518;设有国际美食窗口,定期举办美食节活动。'),
(10, '犀浦学生四食堂', '犀浦', '学生四食堂', '1-2楼', '二楼锦馨苑餐厅', '犀浦校区学生食堂,二楼为锦馨苑餐厅(028-66367123),一楼电话028-66362886。供餐时段:早7:00-10:00、午11:00-13:00、晚17:00-19:00,以现场公示为准。'),
(11, '犀浦五食堂', '犀浦', '学生五食堂', NULL, NULL, '犀浦校区较新食堂之一,2025年秋季学期开学前完成开业准备并投入使用;北侧空地为犀浦北区临时菜鸟驿站(快递点,2026年9月3日起投用)。'),
(12, '犀浦六食堂', '犀浦', '学生六食堂', '1-2楼', NULL, '犀浦校区最新食堂,2026年9月7日起试运行,一、二层先行开放;设家常小厨、特色粉面、峨眉小吃等特色档口,菜品覆盖南北风味。菜品和供餐时段以现场公告及后勤保障部微信公众号为准。'),
(13, '犀浦校区校医院', '犀浦', '校医院', NULL, '二楼医保办公室', '犀浦校区医疗服务点,大学生医保首诊医院;二楼医保办公室受理学生医保手工报销(每周三、周四08:30-11:30、14:00-17:00)。日常咨询028-66366480,校内急救028-66366120,医保咨询028-66366439。'),
(14, '飞碟体育馆(犀浦主体育馆)', '犀浦', '主体育馆(飞碟体育馆)', NULL, NULL, '犀浦校区标志性综合体育馆,外形呈飞碟状得名;篮球、排球场地整场租用300元/场(周六日及节假日),也是全校性活动场馆——2026级"新生第一堂体育课"在此举行,九里校区分会场同步连线。'),
(15, '犀浦羽毛球馆', '犀浦', '羽毛球馆', '1楼', '一楼前台(健身卡办卡点)', '犀浦校区室内羽毛球馆,开放时段15:30-22:00,收费30元/小时(15:30-17:30)、40元/小时(17:30-22:00),持健身卡5折;一楼前台为犀浦校区健身卡办卡点。馆背后为137个室外乒乓球台(免费,24小时)。施工或军训期间可能临时闭馆。'),
(16, '犀浦室外游泳池', '犀浦', '游泳馆/室外游泳池', NULL, NULL, '犀浦校区室外游泳池,每年5月至9月开放,开放时段14:00-20:00,打雷下雨关闭、节假日照常;持健身卡享收费优惠。游泳池旁设物业中心打印店(9:00-18:00)。'),
(17, '犀浦北区体育场(田径场)', '犀浦', '北区体育场/田径场', NULL, NULL, '犀浦校区主要露天田径场,全校性活动的标准场地:2025级学生开学典礼、第124届运动会、学生社团文化节等均在此举行;新生军训期间仅限参训师生进入。'),
(18, '犀浦南区临时菜鸟驿站', '犀浦', '天佑斋2栋西侧空地', NULL, '南区驿站', '犀浦南区快递服务点(2026年9月3日起投用),承接师生包裹揽收、派送;推荐收件地址"四川省成都市郫都区犀安路999号西南交通大学犀浦校区校内南区天佑斋2栋西侧菜鸟驿站",备注"请投递至校内,请勿放置校外点位"。驿站电话19808326007。'),
(19, '犀浦北区临时菜鸟驿站', '犀浦', '五食堂北侧空地', NULL, '北区驿站', '犀浦北区快递服务点(2026年9月3日起投用);推荐收件地址"四川省成都市郫都区犀安路999号西南交通大学犀浦校区校内北区五食堂北侧菜鸟驿站"(备注同南区:请投递至校内)。驿站电话13699467403。'),
(20, '校史博物馆(犀浦)', '犀浦', '校史博物馆(档案馆/校史馆)', NULL, NULL, '展示西南交通大学自1896年建校以来历史校情的专题博物馆。按档案馆2026年7月15日通知,自2026年9月3日起开放时间为周一至周五09:00-12:00、14:00-17:00;法定节假日、寒暑假及特殊安排以专项通知为准。20人及以上团体讲解预约028-66367520;馆内不饮食、不用闪光灯、不录像直播。'),
(21, '保卫处(犀浦校区)', '犀浦', NULL, NULL, NULL, '负责校园安全保卫、户政业务(户口迁移、户籍材料、居住证)、车辆业务(车辆通行证、备案、外来人员入校报备)与政审材料办理;24小时校园报警求助电话犀浦028-66366110。具体办公楼栋以校区导览为准。'),
(22, '九里校区图书馆', '九里', '图书馆', NULL, NULL, '九里校区藏书借阅与自习场所;馆区服务与开放安排以图书馆官网公告为准。楼宇零星维修与物业、电梯保障由后勤24小时值守(028-66361189)。'),
(23, '逸夫馆(九里校区)', '九里', '逸夫馆', '1楼', '正门入口大厅右侧', '九里校区教学楼/综合馆,1楼正门入口大厅右侧设有学籍(在读)证明、成绩单自助打印机,供网上申请后打印纸质证明。'),
(24, '九里学生一食堂', '九里', '学生一食堂', '1-2楼', '二楼扬华餐厅', '九里校区学生食堂,一楼电话028-86465771,二楼扬华餐厅028-87602691;学生社团文化节等活动的九里会场设于校区生活区。'),
(25, '南风餐厅(九里校区)', '九里', '南风餐厅', NULL, NULL, '九里校区餐厅,服务电话028-87601405;也是校车停靠参照点——工作日22:50犀浦至九里"深夜护航"班次在南风餐厅门口下车。'),
(26, '眷诚斋学生宿舍群(九里校区)', '九里', '眷诚斋(若干栋)', NULL, NULL, '九里校区学生宿舍园区,2号楼设物业便利店(6:40-23:00);宿舍设施报修028-87601400,园区水电应急抢修24小时服务。'),
(27, '扬华斋学生宿舍群(九里校区)', '九里', '扬华斋(若干栋)', NULL, NULL, '九里校区学生宿舍园区之一,与眷诚斋同属九里校区主要学生生活区。'),
(28, '詹天佑体育馆(九里校区)', '九里', '詹天佑体育馆', '1楼', '一楼前台(健身卡办卡点)', '九里校区综合体育馆,篮球场地200元/场、羽毛球木板场地30元/小时、塑胶场地40元/小时(9:00-22:00),持健身卡一律5折;一楼前台为九里校区健身卡办卡点。2025级学生开学典礼九里分会场设于本馆。'),
(29, '九里校区信网处服务前台', '九里', '信息化与网络管理处办公楼', '1楼', '服务前台', '九里校区一卡通服务窗口,办理校园卡业务(须出示本人有效证件);信息化与网络管理处同时提供校园网络、VPN、企业微信等服务,一卡通电话028-87600976。'),
(30, '峨眉校区信网处服务大厅(中学楼)', '峨眉', '中学楼', '1楼', '信网处服务大厅', '峨眉校区一卡通服务窗口,办理校园卡业务;峨眉校区一卡通咨询电话0833-5198395。峨眉校区地址:峨眉山市名山路南段402号。'),
(31, '峨眉校区学生服务中心(邮政服务点)', '峨眉', '学生服务中心(学生公寓前)', NULL, '邮政服务点', '峨眉校区邮政与快递服务点,位于学生公寓前学生服务中心;峨眉校区中通、圆通、极兔等快递由韵达代理送件,京东、顺丰派件放学生公寓快递架。');
INSERT INTO knowledge (id, category_id, title, content, source, status, is_verified, effective_from, effective_until) VALUES
(1, 1, '2026级新生报到时间与四校区接待地点', '新生报到一般在9月中旬的周五、周六进行,2026级为9月11日至12日,每天8:00-22:00,由各学院设点接待。犀浦校区接待点在西门扬华大道(南区宿舍与体育馆之间);九里校区在学生宿舍园区内眷诚斋1、2栋至9、10栋中间通道;东部(国际)校区在羽毛球馆(E体育馆);峨眉校区在风雨棚运动场。迎新区域到宿舍之间有免费校内摆渡车。智慧城市与交通学院、利兹学院的本科新生在东部(国际)校区报到,别走错校区。到校当天认准学院迎新棚,凭录取通知书办理报到手续。', '西南交通大学党委学生工作部、党委研究生工作部《关于做好2026级学生迎新工作的通知》', 'published', 1, '2026-08-10', '2026-09-30'),
(2, 1, '网上预报到:迎新网与官方公众号怎么登录', '拿到录取通知书后第一件事是完成"网上预报到"。2026级本科新生、预科生、第二学士学位学生的预报到时间为8月10日至18日,研究生新生为7月20日至30日。办理入口:手机端关注微信公众号"西南交通大学学生工作部"(本科)或"西南交通大学研工部"(研究生);电脑端登录迎新网 freshman.swjtu.edu.cn。登录账号:本科和预科生用考生号,第二学士学位用身份证号,研究生用学号;初始密码为本人身份证号第12到17位(港澳台侨学生为证件号码后6位),登录后建议尽快修改。', '西南交通大学党委学生工作部、党委研究生工作部《关于做好2026级学生迎新工作的通知》', 'published', 1, '2026-08-10', '2026-09-30'),
(3, 1, '迎新物品统一领取:一卡通、文化衫、宿舍钥匙在哪领', '开学前学校把新生"大礼包"集中放到各校区,2026级为9月8日领取。犀浦校区:新生一卡通在图书馆B区一楼信网处前台领取,文化衫等物料在天佑斋3号楼1楼红色驿站,宿舍钥匙在公寓管理与服务中心办公室;面向除经管、公管、智慧、利兹外的本科生。九里校区:一卡通在信网处一楼服务大厅,文化衫等在逸夫馆4104教室,宿舍钥匙在眷诚斋1号楼公寓管理与服务中心办公室;面向研究生、预科生和经管、公管本科新生。智慧学院、利兹学院本科生及第二学士学位新生物料领取按东部(国际)校区管委会、峨眉校区管委会安排执行。', '西南交通大学党委学生工作部、党委研究生工作部《关于做好2026级学生迎新工作的通知》', 'published', 1, '2026-08-10', '2026-09-30'),
(4, 1, '本科生军训时间:开学典礼后连训两周', '新生报到注册后紧接着就是开学典礼和军训。2026级新生9月11日至12日报到注册,9月13日举行开学典礼,本科生军训从9月13日持续到9月26日,共约两周。军训期间按连队编制管理,新生体检也以军训连队为单位统一组织。军训是本科培养的必修环节,原则上全员参加,有身体原因不能参加的可申请免训或缓训。军训前学校统一发放军训服装,按学院通知时间领取并试穿;夏天训练注意防晒补水。', '西南交通大学党委学生工作部《暑假学生工作相关安排》;保卫处《关于做好2026级本科生军训服装发放工作的通知》', 'published', 1, '2026-09-08', '2026-09-26'),
(5, 1, '军训免训、缓训怎么申请', '因身体伤残、患有特殊疾病等原因不适宜参加高强度运动的2026级本科生,可在军训开始前申请免训(不参加)或缓训(推迟到下一年级)。申请要在军训开始前向所在学院提交书面申请及相关证明材料(如三甲医院或校医院出具的诊断证明),填写《西南交通大学本科生军事技能训练免训、缓训申请表》,经学院和学校审核同意后生效,不要自行缺席。保卫处每年9月上旬发布当年通知,具体表格和受理流程以当年通知和学院学工组要求为准。', '西南交通大学保卫处《关于办理军训缓训或免训相关工作的通知》(2026-09-08)', 'published', 1, '2026-09-08', '2026-09-26'),
(6, 1, '新生入学体检:时间、地点、要带什么', '新生入学要参加学校统一组织的入校体检。2026级本科生九里校区安排在9月18日上午,犀浦校区为9月19日至24日,时段8:00-11:30和13:30-17:00;九里、犀浦本科生以军训连队为单位统一组织,不用自己预约;东部(国际)校区和峨眉校区由各单位另行通知。体检当天带二代身份证或护照等有效证件、1张1寸免冠照片和已签署的传染病预防健康教育处方;体检前先完成缴费并在迎新网填报健康信息;前一天饮食清淡、不喝酒、保证睡眠。咨询电话:九里028-87600480,犀浦028-66366480。', '西南交通大学医院《关于2026级新生体检工作安排的通知》', 'published', 1, '2026-09-03', '2026-09-24'),
(7, 1, '大学生医保:参保标准、缴费渠道与待遇期', '大学生医保在成都按城乡居民基本医疗保险参保,看病报销全靠它,建议新生都办。以2026年度为例:基本医保400元/人,可自愿加购大病医疗互助补充保险48元/人,合计448元/人(长护险个人不缴)。集中参保缴费期一般为9月到次年2月底,错过集中缴费期,待遇要从缴费后第91天起才能享受,尽量在报到季就办。在成都参保前须先暂停原户籍地参保关系。缴费渠道:微信"四川税务"公众号-办税缴费-社保缴费-城乡居民医疗保险;参保成功可在"成都税务"公众号查缴费记录。', '西南交通大学医院《关于2026年度大学生医疗保险缴费的通知》及峨眉校区缴费通知', 'published', 1, '2026-09-01', '2027-02-28'),
(8, 1, '党组织关系转接:线上办理,找对学院党委全称', '新生党员的党组织关系原则上通过全国党员管理信息系统线上转接,一般不再开纸质介绍信。由原党组织在系统里发起转出,转入单位要选对学院党委全称,格式为"中共西南交通大学××学院委员会",不清楚先问辅导员或学院党务老师。在本校升学的党员(本科升研、研升博)不需要自己办转接,9月初由学院党委在系统里直接操作。转接完成后及时向学院报到确认,避免组织关系"悬空"。各学院每年8、9月发布新生党员组织关系转接通知,以本学院版本为准。', '西南交通大学信息科学与技术学院《关于开展2026年新生党员组织关系转接工作的通知》', 'published', 1, '2026-08-20', '2026-10-31'),
(9, 1, '团组织关系转接:智慧团建系统操作', '新生团员的团组织关系通过"智慧团建"系统网上转接:登录系统,点击"关系接转",填写转出和转入团组织信息后提交审批;转接申请可由原学校团组织发起,也可由接收团组织发起,一边办即可。各学院团委会在新生入学一个月内在智慧团建系统创建新生团支部并分配新生完成接收,开学后留意学院团委通知,主动核对团籍是否落到新支部。转接完成前别退原团支部,团员档案材料按学院要求提交。', '西南交通大学信息科学与技术学院《关于开展2026级新生团员团组织关系转接工作的通知》', 'published', 1, '2026-08-20', '2026-10-31'),
(10, 1, '绿色通道与助学贷款:家庭经济困难新生先入学后缴费', '家庭经济困难的新生不用为学费发愁:学校在迎新期间设"绿色通道",缓缴学费也能先办理报到入学,报到时向学院说明情况、经"绿色通道"完成手续即可。学费筹措优先推荐办理生源地信用助学贷款(在家乡资助中心办,凭受理证明回执到校登记);已成功办理生源地贷款并提交回执、且贷款金额覆盖学费住宿费的学生,不需要再办理学费缓缴。贷款回执交到学院统一登记汇总,别拖到截止日期。入学后还可申请国家助学金、勤工助学和临时困难补助。', '西南交通大学党委学生工作部迎新通知;生命科学与工程学院学费缓缴通知;扬华素质网学生资助政策页', 'published', 1, '2026-08-10', '2026-09-30'),
(11, 1, '户口迁移:自愿办理,保管好户口迁移证', '新生户口迁入学校遵循自愿原则,可迁可不迁。决定迁的同学,凭录取通知书到户籍所在地公安机关办理《户口迁移证》,证上须加盖当地公安机关户口专用章,报到注册后按保卫处通知提交落户材料。以2026级为例:保卫处9月初发布《新生入户须知》,户口注册自9月11日开始办理;保卫处汇总后将学籍信息上传"四川人口信息服务网",落户由公安机关办理,预计11月初完成。落户完成前妥善保管户口迁移证,千万别弄丢。不迁户口的同学无需办理。', '西南交通大学保卫处《西南交通大学新生入户须知》(2026-09-03)', 'published', 1, '2026-09-03', NULL),
(12, 1, '教材领取:教务处教材服务中心', '新生教材一般由学校统一征订、随报到和开课安排发放,领取时间地点以学院和教务处通知为准,不用自己先买一大堆。教务处教材服务中心负责教材征订与领用,办公地点在犀浦校区二号教学楼,电话028-66366256;教材领用可在教务系统里发起申请。每学期开学前后,本科生院教学事务管理网站会发布教材征订、领用通知,选课结束后记得核对课表对应的教材清单。自己淘二手书或电子书也可以,注意老师指定版本是否一致。', '西南交通大学教务处教材服务中心办事页(教材领用申请)', 'published', 1, '2026-09-01', NULL),
INSERT INTO service_guide (id, title, department, location_id, service_time, materials, process, is_enabled) VALUES
(1, '校园一卡通办理与充值', '信息化与网络管理处(信网处)', 2, '受理时限:立即办理;前台服务时间以信网处公布为准', '1. 本人办卡/充值:出示本人有效证件(身份证、学生证等); 2. 社会用工办卡:本人身份证+与学校人事处或校内二级单位签订的合同; 3. 临时人员办卡:本人身份证+校内单位出具的有效证明。', '1. 前往就近服务网点:犀浦校区图书馆1楼B区信网处服务前台、九里校区信网处1楼服务前台、峨眉校区中学楼1楼信网处服务大厅; 2. 出示证件,现场办理新办卡、充值或销户; 3. 自助充值三渠道:用本人成都本地工行储蓄卡或四川省内建行储蓄卡在圈存机自助充值;或用支付宝、翼支付的校园一卡通应用充值(充值完成后须在食堂消费POS机上刷卡一次把金额领取进卡);或持储蓄卡到信网处前台POS机刷卡/现金充值; 4. 卡片问题(未到账、坏卡)保留订单信息到前台查询处理。电话:028-87600976、028-66366569、0833-5198395。', 1),
(2, '校园网账号开通(开户)', '信息化与网络管理处(信网处)', 2, '受理时限:立即开通;前台服务时间以信网处公布为准', '1. 学生:学生证或一卡通+身份证; 2. 教师:工作证或一卡通+身份证; 3. 单位用户:单位盖章证明+经办人工作证或一卡通+身份证; 4. 短期培训人员:身份证+培训时间段证明+培训证。', '1. 打开用户自助服务系统 http://service.swjtu.edu.cn,点"自助注册"如实填写个人信息(用户名不要带 @cer 或 @wt 后缀); 2. 预注册完成后,持有效证件到信网处前台正式开通并缴费:九里校区信网处1楼大厅、犀浦校区图书馆1楼信网处前台、峨眉校区中学楼1楼服务前台; 3. 登录自助服务系统"自助缴费"充值后即可使用;校园网实行实名制认证登录; 4. 接入类型二选一:教育网账号(三校区漫游)或中国联通融合套餐账号(成都两校区)。咨询:028-87600223、028-66366561,网络服务QQ群1043566925。', 1),
(3, '学生邮箱(@my.swjtu.edu.cn)开通', '信息化与网络管理处(犀浦校区图书馆B156,电话028-66366559)', 2, '自助注册即时生效;人工申请1个工作日内办结(短信/邮件通知)', '1. 自助注册:无需材料,在线填写即可; 2. 人工申请:本人有效身份证件+《西南交通大学电子邮箱个人用户业务申请表和书面申请》(信网处主页下载),填好打印后经本单位领导签字、加盖公章递交。', '1. 打开在线申请入口 http://mailreg.swjtu.edu.cn/ 自助注册(教职工、学生首选方式);邮箱实名登记,一人只能有一个实名账户; 2. 无法自助办理的按上述材料走人工申请,交到信网处邮箱业务窗口; 3. 开通后学生邮箱登录入口 https://my.swjtu.edu.cn/,后缀 @my.swjtu.edu.cn(教职工为 @swjtu.edu.cn); 4. 使用限制:每15分钟发信上限150封、24小时内上限500封,一个IP每15分钟连接数上限200;发大附件可参考信网处《如何利用学校邮箱来发送比较大的附件》指南。', 1),
(4, '学籍(在读)证明与成绩单打印', '教务处教务科(028-66366252)', 3, '线上申请即时受理;自助打印机按现场开放时间使用', '1. 无需纸质材料,全程线上办理; 2. 登录教学服务网上办事平台 jiaowu.swjtu.edu.cn,选择"本科生在读证明"或"成绩单打印"事项。', '1. 在线选择打印份数并完成支付; 2. 申请成功后前往自助打印机,登录平台选择该申请打印(一个申请只能打印一次); 3. 打印机位置:犀浦校区综合楼2楼教务处旁及学生服务大厅(2教),九里校区逸夫馆1楼正门入口大厅右侧; 4. 电子版证明通过办事平台"可信电子证明申请"入口办理;毕业生、校友另有独立办理栏目。', 1);
INSERT INTO campus_activity (id, title, start_time, end_time, location_id, signup_method, target_audience, description, is_enabled) VALUES
(1, '西南交通大学2025级学生开学典礼', '2025-09-07 08:00:00', '2025-09-07 12:00:00', 17, '无需报名,2025级新生按学院组织参加', '2025级全体新生、校领导、教师代表', '2025级学生开学典礼于2025年9月7日(星期日)上午在犀浦校区北区体育场主会场举行,并通过网络连线在九里校区詹天佑体育馆、大学生会堂、国际会议厅及峨眉校区明诚堂同步举行;校党委书记余敏明、校长闫学东等全体校领导出席。具体时刻以学校通知为准。(2025年)', 1),
(2, '西南交通大学第124届运动会暨建校129周年校庆运动会', '2025-04-11 00:00:00', '2025-04-12 23:59:59', 17, '以学院为单位报名参赛(按运动会竞赛规程执行)', '全校师生(各学院代表队)', '2025年4月11日至12日在犀浦校区北区田径场举行,4月11日开幕(开幕式8:30,8:00前北区田径场外围整队候场);运动会与建校129周年校庆结合举办,各学院组织方阵与参赛队伍,期间产生多项校纪录。具体赛程以竞赛规程为准。(2025年,第124届)', 1),
(3, '第五届"运达杯"体育节开幕暨师生环校跑', '2025-11-23 00:00:00', '2025-11-23 23:59:59', 17, '按体育部/学院组织报名参赛', '全校师生', '2025年11月23日在犀浦校区北区运动场举行,旨在践行"健康第一"教育理念、推进"五育并举",以体育精神迎接学校130周年校庆;校党委常委、副校长康国政及赞助企业代表出席开幕式。体育节期间还举办师生乒乓球赛(11月27日、12月6日在犀浦校区体育馆)等系列赛事。具体开跑时刻以体育部通知为准。(2025年,第五届)', 1),
(4, '西南交通大学第26届学生社团文化节暨校级学生组织招新活动("百团大战")', '2026-10-15 17:30:00', '2026-10-15 23:59:59', 17, '学生现场到各社团摊位咨询报名加入;社团与校级组织按团委通知申请摆点', '全校学生(以本科新生为主)、各学生社团及校级学生组织', '即学生俗称的"百团大战"——学生社团开放日暨校级学生组织招新大会,由校团委主办、学生社团联合会承办,每年秋季学期开学初举行,百余个社团和校级组织集中摆点展示、表演并招募新成员。第26届于2026年10月15日17:30在犀浦校区田径场举行,各指导单位须指派至少一名指导教师现场全程指导。结束时刻以团委通知为准;社团14:00起入场布点,17:00前完成。(2026年,第26届)', 1),
(5, '西南交通大学2026级新生第一堂体育课', '2026-10-08 15:30:00', '2026-10-08 18:00:00', 14, '无需报名,2026级新生按体育课教学班入场', '2026级全体本科新生', '2026年10月8日(周四)下午15:30在犀浦校区飞碟体育馆开讲,主题为"生命因运动而精彩",线上线下相结合:犀浦校区新生按体育课教学班进入飞碟体育馆就座,九里校区设学生会堂东部等分会场同步参与;各学院提前告知新生按引导指引入场。结束时刻以体育学院通知为准。(2026年)', 1),
(6, '第二十五届学生社团文化节暨校级学生组织招新活动', '2025-09-25 00:00:00', '2025-09-25 23:59:59', 17, '学生现场到社团摊位报名', '全校学生、100余个学生社团与20余个校级学生组织', '以"青春砥砺奋进 共赴百卅之约"为主题,2025年9月25日在犀浦校区和九里校区同时举行,100余个学生社团、20余个校级组织参加,是2025年秋季学期的全校性社团招新活动。当日具体时段以团委通知为准。(2025年,第25届)', 1);
INSERT INTO course (id, name, code, semester, description) VALUES
(1, '高等数学', 'SEE-001', '2026-2027-1', '全校理工科各专业公共基础必修课,由数学学院公共数学教学研究部承担"高等数学系列课程"的教学管理。课程讲授极限、一元微积分、级数等分析基础,是后续专业课程的核心数学工具。选课通知中另设《高等数学(提高)》作为公共任选课供学有余力者修读。课程代码以教务系统为准。'),
(2, '线性代数', 'SEE-002', '2026-2027-1', '全校公共基础必修课,由数学学院公共数学教学研究部承担"线性代数系列课程"教学管理,内容含行列式、矩阵、向量组、线性方程组、二次型等,是工程与经管类专业的核心数学基础课。课程代码以教务系统为准。'),
(3, '大学英语', 'SEE-003', '2026-2027-1', '全校公共基础必修课,由外国语学院大学英语第一、第二、第三教研室承担教学。课程按分级教学组织,兼顾听说读写译综合能力训练,并与全国大学英语四六级考试(CET)衔接。课程代码以教务系统为准。'),
(4, '体育(Ⅰ)', 'SEE-004', '2026-2027-1', '公共必修课,由体育学院开设,实行三学年六学期分级、分层、分项目"熟练技能"教学模式,学生"三自主"选课(自主选择项目、老师、时间)。2026-2027-1学期面向2026级开设体育Ⅰ,新生按校区与课次分批选课,可选篮球、羽毛球、乒乓球、游泳等项目(以当学期开课目录为准)。课程代码以教务系统为准。'),
(5, '思想道德与法治', 'SEE-005', '2026-2027-1', '本科生思想政治理论课(公共必修),由马克思主义学院承担,2026-2027学年第一学期选课通知将其列为大一新生公共必选课程之一,面向低年级开设,引导新生完成从中学到大学的思想与法治观念衔接。课程代码以教务系统为准。'),
(6, '中国近现代史纲要', 'SEE-006', '2026-2027-1', '本科生思想政治理论课(公共必修),由马克思主义学院承担,在2026-2027学年第一学期选课通知的公共必选课程列表中。课程讲述中国近现代历史进程与历史经验,帮助学生理解历史与人民的选择。课程代码以教务系统为准。'),
(7, '马克思主义基本原理', 'SEE-007', '2026-2027-1', '本科生思想政治理论课(公共必修),由马克思主义学院承担,在2026-2027学年第一学期选课通知的公共必选课程列表中,讲授马克思主义哲学、政治经济学与科学社会主义基本原理。课程代码以教务系统为准。'),
(8, '毛泽东思想和中国特色社会主义理论体系概论', 'SEE-008', '2026-2027-1', '本科生思想政治理论课(公共必修),由马克思主义学院承担,在2026-2027学年第一学期选课通知的公共必选课程列表中,系统讲授马克思主义中国化的理论成果。课程代码以教务系统为准。'),
(9, '习近平新时代中国特色社会主义思想概论', 'SEE-009', '2026-2027-1', '本科生思想政治理论课(公共必修),由马克思主义学院承担,在2026-2027学年第一学期选课通知的公共必选课程列表中。课程代码以教务系统为准。');
